import type { CSSProperties } from 'react';
import {
  darkMarkPlatforms,
  grayPlatforms,
  platformLabels,
  socialPlatforms,
  type SocialPlatform,
} from '../../icons/social-names';
import './SocialIcon.css';

/* The Figma "Social icon" set (src/icons/social, generated by `npm run icons`). */
const files = import.meta.glob<string>('../../icons/social/*.svg', { eager: true, query: '?url', import: 'default' });
const urlOf = (file: string) => files[`../../icons/social/${file}.svg`];

export { socialPlatforms, grayPlatforms, platformLabels, type SocialPlatform };

/** Figma "Social icon" (68:17086): Platform × Style. */
export type SocialIconProps = {
  /** Figma Platform. "X (Twitter)" is `x`. */
  platform: SocialPlatform;
  /**
   * Figma Style: Brand (the platform's own colours) or Gray (one colour, the `icon-base-500` token).
   * Slack, Zapier, Notion and Dropbox have no Gray version in Figma and stay Brand.
   */
  variant?: 'brand' | 'gray';
  /** Size in px. The guidelines use 20 and 24, matched to the component and text size. */
  size?: 20 | 24;
  /**
   * Accessible name, such as "LinkedIn". Only for an icon that stands alone and means something;
   * leave it out when the icon sits next to text or the parent link or button already has a name.
   */
  label?: string;
  className?: string;
};

/**
 * A social platform logo. Brand icons are pictures with the platform's colours; near-black marks
 * (X, Apple, GitHub, TikTok, Tumblr, AngelList, Layers) switch to white in the dark theme, where Figma's
 * black would disappear. Gray icons are drawn as a CSS mask, so their colour comes from the token.
 */
export function SocialIcon({ platform, variant = 'brand', size = 24, label, className = '' }: SocialIconProps) {
  const gray = variant === 'gray' && (grayPlatforms as readonly string[]).includes(platform);
  const dark = !gray && (darkMarkPlatforms as readonly string[]).includes(platform);
  const style = {
    '--social-src': `url("${urlOf(`${platform}-${gray ? 'gray' : 'brand'}`)}")`,
    ...(dark && { '--social-src-dark': `url("${urlOf(`${platform}-brand-dark`)}")` }),
    '--social-size': `${size}px`,
  } as CSSProperties;
  const a11y = label ? { role: 'img', 'aria-label': label } : { 'aria-hidden': true };
  return (
    <span className={`grg-social-icon grg-social-icon--${gray ? 'gray' : 'brand'} ${className}`} style={style} {...a11y} />
  );
}
